command:
const mod = game.modules.get('draw-steel-combat-tools');
const stealth = mod?.api?.stealth;
const sight = mod?.api?.sight;
const say = (title, body) => ChatMessage.create({
  content: `<div class="dsct-stealth-report"><h3>${title}</h3>${body}</div>`,
  whisper: [game.user.id],
});
if (!stealth || !sight) {
  ui.notifications.error('DSCT stealth api missing. Is the module active, and has the world been reloaded since it was installed?');
  return;
}
const me = canvas.tokens.controlled[0];
if (!me) {
  ui.notifications.warn('Select the token you are testing with first.');
  return;
}
const nameOf = (id) => canvas.tokens.get(id)?.name ?? id;
const list = (names) => names.length ? '<ul><li>' + names.join('</li><li>') + '</li></ul>' : '<p><em>Nobody.</em></p>';

const ids = [...stealth.hiddenFrom(me)];
const status = me.actor?.statuses?.has('dsctHidden') ? 'yes' : 'no';
say(`${me.name} is hidden from`, list(ids.map(nameOf)) +
  `<p><em>Hidden status on the actor: ${status}.</em></p>`);
